"""Binary search — contains an off-by-one bug."""
from typing import Optional


def binary_search(arr: list, target) -> int:
    """Return index of target in sorted arr, or -1 if not found."""
    low, high = 0, len(arr)
    while low < high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid  # BUG: should be mid + 1
        else:
            high = mid
    return -1


def search_range(arr: list, target) -> tuple[int, int]:
    """Return (first_index, last_index) of target, or (-1, -1) if not found."""
    def find_left(arr, target):
        low, high = 0, len(arr)
        while low < high:
            mid = (low + high) // 2
            if arr[mid] < target:
                low = mid  # BUG: should be mid + 1
            else:
                high = mid
        return low if low < len(arr) and arr[low] == target else -1

    def find_right(arr, target):
        low, high = 0, len(arr)
        while low < high:
            mid = (low + high) // 2
            if arr[mid] <= target:
                low = mid  # BUG: should be mid + 1
            else:
                high = mid
        return low - 1 if low > 0 and arr[low - 1] == target else -1

    left = find_left(arr, target)
    if left == -1:
        return (-1, -1)
    return (left, find_right(arr, target))

