import pytest
from binary_search import binary_search, search_range


def test_found_in_middle():
    assert binary_search([1, 3, 5, 7, 9], 5) == 2


def test_found_at_start():
    assert binary_search([1, 3, 5, 7, 9], 1) == 0


def test_found_at_end():
    assert binary_search([1, 3, 5, 7, 9], 9) == 4


def test_not_found():
    assert binary_search([1, 3, 5, 7, 9], 4) == -1


def test_empty_list():
    assert binary_search([], 5) == -1


def test_single_element_found():
    assert binary_search([42], 42) == 0


def test_single_element_not_found():
    assert binary_search([42], 99) == -1


def test_search_range_found():
    assert search_range([1, 2, 2, 2, 3], 2) == (1, 3)


def test_search_range_single():
    assert search_range([1, 2, 3], 2) == (1, 1)


def test_search_range_not_found():
    assert search_range([1, 2, 3], 9) == (-1, -1)


def test_search_range_empty():
    assert search_range([], 1) == (-1, -1)
